// Generated by `pnpm nx g @app/generators:action views.delete`. Requests go through the real router
// with createTestEngine().inject. They fail until createViewsDeleteAction is implemented; do not weaken them.
import { viewsDelete } from '@app/contracts';
import { createRoleAuthorizer } from '@app/kernel';
import {
  createViewsCreateAction,
  createViewsDeleteAction,
  createWorkspaceFakeDeps,
} from '@app/svc-workspace';
import { afterEach, describe, expect, it } from 'vitest';

import { createTestEngine, type TestEngine } from '../create-test-engine.ts';

const subject = () => createViewsDeleteAction(createWorkspaceFakeDeps());
const def = viewsDelete;
const KEY = 'generated-spec-key-0001';
let engine: TestEngine;

afterEach(async () => {
  await engine.close();
});

describe('DELETE /views/{viewId}', () => {
  it('GP-1 (OQ-783) the route runs views.delete with no connection armed: it declares scope local, so the prod lock does not apply and the call answers 200', async () => {
    const deps = createWorkspaceFakeDeps();
    engine = createTestEngine({
      actions: [createViewsCreateAction(deps), createViewsDeleteAction(deps)],
    });
    const made = await engine.inject({
      method: 'POST',
      path: '/views',
      payload: { name: 'Busy queues', kind: 'queues', definition: {} },
      headers: { 'idempotency-key': `${KEY}-create` },
    });
    const viewId = made.json<{ view: { id: string } }>().view.id;
    const answer = await engine.inject({
      method: 'DELETE',
      path: `/views/${viewId}`,
      payload: {},
      headers: { 'idempotency-key': KEY },
    });

    // The router sends no environment class, so the call is "prod". The action declares scope 'local' (it
    // changes only the engine's own state), so the lock has nothing to arm and lets it through (OQ-783).
    expect(answer.statusCode).toBe(200);
    expect(def.output.safeParse(answer.json()).success).toBe(true);
    expect(made.statusCode).toBe(200);
    expect(engine.audit.attempts).toHaveLength(2);
  });

  it('GP-2 a request without the launch token is refused and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'DELETE',
      path: '/views/sample',
      authenticated: false,
    });

    expect(answer.statusCode).toBe(401);
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-3 a caller that does not hold workspace.write gets 403 and nothing runs', async () => {
    engine = createTestEngine({
      actions: [subject()],
      authorizer: createRoleAuthorizer({}),
    });
    const answer = await engine.inject({
      method: 'DELETE',
      path: '/views/sample',
      payload: {},
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(403);
    expect(answer.json()).toMatchObject({ code: 'FORBIDDEN_RBAC' });
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('GP-4 input that breaks the contract is a 400 Problem and nothing runs', async () => {
    engine = createTestEngine({ actions: [subject()] });
    const answer = await engine.inject({
      method: 'DELETE',
      path: '/views/sample',
      payload: { unexpected: true },
      headers: { 'idempotency-key': KEY },
    });

    expect(answer.statusCode).toBe(400);
    expect(answer.json()).toMatchObject({ code: 'VALIDATION_FAILED' });
    expect(engine.audit.attempts).toEqual([]);
  });

  it('GP-5 a method nothing is bound to on the path is 405, and Allow lists the bound ones', async () => {
    engine = createTestEngine({ actions: [subject()] });

    const answer = await engine.inject({
      method: 'PATCH',
      path: '/views/sample',
    });

    expect(answer.statusCode).toBe(405);
    expect(answer.headers.allow).toBe('DELETE');
  });
});
